    segment_u_max(s) + 1
}

#[verifier::external_body]
pub proof fn lemma_segment_get_unused_uniq_field(s: Set<SegmentId>)
    ensures forall |id: SegmentId| s.contains(id) ==> id.uniq != segment_get_unused_uniq_field(s)
{
    unimplemented!()
}

